package update

import("crypto/ed25519";"crypto/sha256";"encoding/base64";"encoding/hex";"encoding/json";"errors";"fmt";"io";"net/http";"os";"path/filepath";"strings")
type Manifest struct{Version string `json:"version"`;URL string `json:"url"`;SHA256 string `json:"sha256"`;Signature string `json:"signature"`}
func(m Manifest)signedPayload()[]byte{return []byte(m.Version+"\n"+m.URL+"\n"+strings.ToLower(m.SHA256)+"\n")}
func VerifyManifest(m Manifest,key ed25519.PublicKey)error{if m.Version==""||m.URL==""||len(m.SHA256)!=64{return errors.New("incomplete update manifest")};sig,err:=base64.StdEncoding.DecodeString(m.Signature);if err!=nil{return errors.New("invalid manifest signature encoding")};if !ed25519.Verify(key,m.signedPayload(),sig){return errors.New("invalid update manifest signature")};return nil}
func ParseManifest(data []byte,key ed25519.PublicKey)(Manifest,error){var m Manifest;if err:=json.Unmarshal(data,&m);err!=nil{return m,err};return m,VerifyManifest(m,key)}
type Stager struct{HTTP *http.Client;PublicKey ed25519.PublicKey}
func(s Stager)Stage(m Manifest,dst string)error{if err:=VerifyManifest(m,s.PublicKey);err!=nil{return err};h:=s.HTTP;if h==nil{h=http.DefaultClient};resp,err:=h.Get(m.URL);if err!=nil{return err};defer resp.Body.Close();if resp.StatusCode<200||resp.StatusCode>=300{return fmt.Errorf("update download returned %d",resp.StatusCode)};if err:=os.MkdirAll(filepath.Dir(dst),0700);err!=nil{return err};tmp:=dst+".tmp";f,err:=os.OpenFile(tmp,os.O_CREATE|os.O_TRUNC|os.O_WRONLY,0700);if err!=nil{return err};hash:=sha256.New();_,cp:=io.Copy(io.MultiWriter(f,hash),io.LimitReader(resp.Body,512<<20));closeErr:=f.Close();if cp!=nil{return cp};if closeErr!=nil{return closeErr};if hex.EncodeToString(hash.Sum(nil))!=strings.ToLower(m.SHA256){_=os.Remove(tmp);return errors.New("update sha256 mismatch")};return os.Rename(tmp,dst)}
